def salary_band(salary: float) -> str:
    if salary < 35000:
        return "junior"
    if salary < 55000:
        return "mid"
    return "senior"

for title, s in [("Analyst", 38000), ("Lead", 70000)]:
    print(title, salary_band(s))

import json
from pathlib import Path

def load_jobs(path: Path) -> list[dict]:
    try:
        with path.open(encoding="utf-8") as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"No file at {path}, starting empty")
        return []

jobs = load_jobs(Path("data") / "jobs.json")

import logging

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")
log = logging.getLogger(__name__)

def net_price(price: float, discount: float = 0.0) -> float:
    if not 0 <= discount < 1:
        raise ValueError("discount must be between 0 and 1")
    return round(price * (1 - discount), 2)

# test_prices.py  (run: pytest -q)
import pytest

def test_net_price():
    assert net_price(100, 0.2) == 80.0

def test_bad_discount():
    with pytest.raises(ValueError):
        net_price(100, 1.5)

