def average_salary(jobs):
    if not jobs:
        return 0
    return round(sum(j["salary"] for j in jobs) / len(jobs))

from collections import Counter

def word_counts(text):
    return Counter(text.lower().split())

from pathlib import Path

def count_errors(path: str) -> int:
    return sum(1 for line in Path(path).read_text().splitlines() if "ERROR" in line)


def test_count_errors(tmp_path):
    log = tmp_path / "app.log"
    log.write_text("INFO ok\nERROR boom\nERROR again\n")
    assert count_errors(log) == 2
